    function answerWith(ok, line, after) { scored(ok); setTimeout(() => show(line, sample(ok ? NEXT_OK : NEXT_BAD, 2).map(([j, r]) => ({ jp: j, ru: r, go: after }))), 650); }
    // «как по-японски?»: показываем перевод, выбираем слово
